const people = $json.people || [];
const companyName = $('Split Companies').item.json.name || "";

// Keywords for decision makers
const highValueTitles = ['vlasnik', 'owner', 'ceo', 'direktor', 'director', 'founder', 'osnivač'];
const mediumValueTitles = ['hr', 'project manager', 'menadžer', 'rukovodilac'];

const scored = people.map(p => {
  const title = (p.title || "").toLowerCase();
  let score = 0;

  // High value decision makers
  if (highValueTitles.some(t => title.includes(t))) score += 10;

  // Medium value
  else if (mediumValueTitles.some(t => title.includes(t))) score += 6;

  // Has LinkedIn URL
  if (p.linkedin_url) score += 3;

  // Has verified email
  if (p.email) score += 2;

  // Location match (Serbia)
  if (p.state && p.state.toLowerCase().includes('serbia')) score += 2;

  return { ...p, decision_maker_score: score, company_name: companyName };
});

// Return top 3 decision makers per company
const topPeople = scored
  .sort((a, b) => b.decision_maker_score - a.decision_maker_score)
  .slice(0, 3)
  .filter(p => p.decision_maker_score >= 6); // Minimum quality threshold

return topPeople.map(p => ({ json: p }));
